{
  "hypotheses": [
    {
      "id": "H1",
      "mechanism": "Insufficient torque authority: The creature's torque authority (baseline.torque_authority=0.08253) is far below the reference (creature.reference.features.tau_ratio=0.9951), causing high torque saturation (baseline.saturation_frac=0.7255, baseline.peak_tau_over_limit_hip=1.0, baseline.peak_tau_over_limit_knee=1.0, baseline.peak_tau_over_limit_ankle=1.0) and preventing the controller from generating necessary forces. Competing explanation: The controller's feedback gains are too high for the available torque, but the same gains work on the reference body because torque authority is sufficient."
    ,
      "evidence": [
        "baseline.torque_authority",
        "creature.reference.features.tau_ratio",
        "baseline.saturation_frac",
        "baseline.peak_tau_over_limit_hip",
        "baseline.peak_tau_over_limit_knee",
        "baseline.peak_tau_over_limit_ankle"
      ]
    ,
      "competing": [
        "The controller's feedback gains are too high for the available torque, but the same gains work on the reference body because torque authority is sufficient."
      ]
    },
    {
      "id": "H2",
      "mechanism": "Gait frequency mismatch: The controller's frequency (baseline.controller_freq_hz=1.555) is 2.42 times the body's natural pendulum frequency (baseline.pendulum_freq_hz=0.6427, baseline.controller_freq_ratio=2.42), leading to an actual step frequency (baseline.step_freq_hz=4.088) much higher than the controller frequency, causing instability. Competing explanation: The high step frequency is a symptom of falling forward, not a cause."
    ,
      "evidence": [
        "baseline.controller_freq_hz",
        "baseline.pendulum_freq_hz",
        "baseline.controller_freq_ratio",
        "baseline.step_freq_hz"
      ]
    ,
      "competing": [
        "The high step frequency is a symptom of falling forward, not a cause."
      ]
    },
    {
      "id": "H3",
      "mechanism": "Incorrect posture control: The torso pitch mean (baseline.pitch_mean_rad=0.1834) and drift (baseline.pitch_drift_radps=0.5964) are positive and large, with pitch at end (baseline.pitch_at_end_rad=1.009) indicating a forward lean that leads to falling (baseline.forward_fall_frac=0.75). Competing explanation: The forward lean is a consequence of insufficient torque to maintain upright posture."
    ,
      "evidence": [
        "baseline.pitch_mean_rad",
        "baseline.pitch_drift_radps",
        "baseline.pitch_at_end_rad",
        "baseline.forward_fall_frac"
      ]
    ,
      "competing": [
        "The forward lean is a consequence of insufficient torque to maintain upright posture."
      ]
    }
  ],
  "probes": [
    {
      "probe_id": "torque_x1_5",
      "hypothesis": "H1",
      "expect": "improves"
    },
    {
      "probe_id": "opt_timing",
      "hypothesis": "H2",
      "expect": "improves"
    },
    {
      "probe_id": "opt_posture",
      "hypothesis": "H3",
      "expect": "improves"
    }
  ]
}

